function getRegionIconById(regionIdOrText) {
  const s = String(regionIdOrText || "").toLowerCase();
  if (s.includes("vinh-long") || s.includes("vĩnh long")) return BRAND_ICONS.vinhLong;
  if (s.includes("ben-tre") || s.includes("bến tre")) return BRAND_ICONS.benTre;
  return BRAND_ICONS.traVinh;
}

