function getFieldworkRecords() {
  try {
    const raw = localStorage.getItem(STORAGE_FIELDWORK_KEY);
    if (!raw) return DEFAULT_FIELDWORK_RECORDS;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.length > 0 ? parsed : DEFAULT_FIELDWORK_RECORDS;
  } catch (e) {
    return DEFAULT_FIELDWORK_RECORDS;
  }
}

function saveFieldworkRecords(list) {
  try {
    localStorage.setItem(STORAGE_FIELDWORK_KEY, JSON.stringify(list));
  } catch (e) {}
}

function copyFull2026SummaryText(dishes) {
  const lines = [
    "HỒ SƠ BẢO TỒN BÁNH TRUYỀN THỐNG KHMER TỈNH VĨNH LONG MỚI (CẬP NHẬT CHUẨN 2026)",
    "Địa giới hành chính 2026: Hợp nhất 3 tỉnh Vĩnh Long, Trà Vinh, Bến Tre thành tỉnh Vĩnh Long mới (vận hành mô hình chính quyền 2 cấp Tỉnh - Xã/Phường theo Nghị quyết 202/2025/QH15 & 1687/NQ-UBTVQH15).",
    ""
  ];
  dishes.forEach((d) => {
    const pInfo = getPreservationInfo(d.id);
    lines.push(`${d.id}. ${d.name} (${d.khmerName}) — Mã QR: ${d.qrCodeId} | Trang riêng: ${getDishPageFileName(d)}`);
    lines.push(`   • Khu vực & Địa danh: ${cleanCategoryLabel(d.categoryName)} — ${d.localSpot}`);
    lines.push(`   • Xuất xứ: ${d.originExact}`);
    lines.push(`   • Công thức: ${d.recipeExact}`);
    lines.push(`   • Thời gian: ${d.prepTime} | Bảo quản: ${d.shelfLife} | Chi phí mẻ chuẩn (${d.baseBatch} ${d.batchUnit}): ~${formatVndCurrency(d.estimatedCostPerBaseBatch)} | Tình trạng: ${pInfo.badge}`);
    lines.push("");
  });
  copyTextSafe(lines.join("\n"));
  showAppToast("Đã sao chép toàn bộ Hồ sơ bánh truyền thống chuẩn năm 2026!");
}


function cleanCategoryLabel(catStr) {
  return String(catStr || "")
    .replace(/^[0-9.]+\s*/, "")
    .replace(/^Khu vực\s*/i, "")
    .trim();
}

