function getTastedCakeIds() {
  try {
    const raw = localStorage.getItem(STORAGE_TASTED_KEY);
    if (!raw) return [1, 7];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [1, 7];
  } catch (e) {
    return [1, 7];
  }
}

function toggleTastedCakeId(cakeId) {
  const numId = parseInt(cakeId, 10);
  const current = getTastedCakeIds();
  const wasIn = current.includes(numId);
  const next = wasIn ? current.filter((id) => id !== numId) : [...current, numId];
  try {
    localStorage.setItem(STORAGE_TASTED_KEY, JSON.stringify(next));
  } catch (e) {}
  if (!wasIn) {
    triggerCelebrationConfetti();
  }
  updateTopPassportBadge();
  return next;
}

function updateTopPassportBadge() {
  const count = getTastedCakeIds().length;
  const el = document.getElementById("top-passport-count-label");
  if (el) {
    el.textContent = count > 0 ? `Hộ Chiếu Ẩm Thực (Đã thử)` : `Hộ Chiếu Ẩm Thực`;
  }
}

function getPassportRankInfo(count) {
  if (count >= 12) {
    return { title: "Sành Ăn Số 1 Vĩnh Long", badge: "👑 Hạng Kim Cương", color: "#B91C1C", nextHint: "Bạn đã chinh phục trọn vẹn bản đồ bánh dân gian 3 vùng!" };
  }
  if (count >= 8) {
    return { title: "Sành Bánh 3 Vùng", badge: "🔥 Hạng Vàng", color: "#D97706", nextHint: `Thử thêm ${12 - count} món nữa để đạt danh hiệu Đại Sứ Ẩm Thực!` };
  }
  if (count >= 4) {
    return { title: "Mê Bánh Dân Gian", badge: "🥥 Hạng Bạc", color: "#0D7A5F", nextHint: `Thử thêm ${8 - count} món nữa để lên hạng Nghệ Nhân Sành Ăn!` };
  }
  return { title: "Người Mới Khám Phá", badge: "🌱 Khởi Hành", color: "#047857", nextHint: `Đánh dấu thêm ${Math.max(1, 4 - count)} món bánh bạn đã từng thưởng thức!` };
}

function getRadarAxesScores(cake) {
  // 5 axes: [Độ Dẻo, Vị Béo, Hương Lá, Độ Giòn/Xốp, Bảo Quản]
  const map = {
    1: [98, 88, 96, 45, 96],
    2: [85, 86, 95, 78, 50],
    3: [82, 88, 75, 92, 72],
    4: [65, 72, 60, 98, 98],
    5: [95, 90, 78, 55, 70],
    6: [92, 85, 72, 60, 68],
    7: [94, 95, 88, 70, 85],
    8: [84, 88, 68, 95, 60],
    9: [80, 86, 65, 94, 65],
    10: [86, 84, 96, 80, 65],
    11: [90, 96, 94, 65, 55],
    12: [94, 92, 95, 72, 60],
    13: [96, 94, 92, 50, 78],
    14: [85, 98, 80, 92, 50]
  };
  return map[cake.id] || [85, 85, 85, 80, 70];
}

function buildVersusRadarSvg(comparedDishes) {
  const axes = ["Độ Dẻo", "Vị Béo Dừa", "Hương Thảo Mộc", "Độ Giòn/Xốp", "Bảo Quản"];
  const cx = 160;
  const cy = 145;
  const maxR = 92;
  const colors = [
    { stroke: "#0D7A5F", fill: "rgba(13, 122, 95, 0.22)" },
    { stroke: "#E11D48", fill: "rgba(225, 29, 72, 0.20)" },
    { stroke: "#D97706", fill: "rgba(217, 119, 6, 0.22)" }
  ];

  const getPoint = (axisIdx, pct) => {
    const angle = -Math.PI / 2 + (axisIdx * 2 * Math.PI) / axes.length;
    const r = (pct / 100) * maxR;
    return [cx + r * Math.cos(angle), cy + r * Math.sin(angle)];
  };

  const rings = [25, 50, 75, 100]
    .map((pct) => {
      const pts = axes.map((_, i) => getPoint(i, pct).map((n) => n.toFixed(1)).join(",")).join(" ");
      return `<polygon points="${pts}" fill="none" stroke="#CBD5E1" stroke-width="1" stroke-dasharray="${pct === 100 ? "none" : "3 3"}" />`;
    })
    .join("");

  const spokes = axes
    .map((label, i) => {
      const [xEnd, yEnd] = getPoint(i, 100);
      const [xLbl, yLbl] = getPoint(i, 124);
      return `
        <line x1="${cx}" y1="${cy}" x2="${xEnd.toFixed(1)}" y2="${yEnd.toFixed(1)}" stroke="#94A3B8" stroke-width="1" />
        <text x="${xLbl.toFixed(1)}" y="${yLbl.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" fill="#1E293B" font-size="10" font-weight="800">${label}</text>
      `;
    })
    .join("");

  const polygons = comparedDishes
    .slice(0, 3)
    .map((cake, idx) => {
      const scores = getRadarAxesScores(cake);
      const pts = scores
        .map((sc, axisIdx) => getPoint(axisIdx, sc).map((n) => n.toFixed(1)).join(","))
        .join(" ");
      const col = colors[idx % colors.length];
      const dots = scores
        .map((sc, axisIdx) => {
          const [px, py] = getPoint(axisIdx, sc);
          return `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="3.5" fill="${col.stroke}" stroke="#FFFFFF" stroke-width="1.2" />`;
        })
        .join("");
      return `
        <polygon points="${pts}" fill="${col.fill}" stroke="${col.stroke}" stroke-width="2.4" />
        ${dots}
      `;
    })
    .join("");

  return `
    <svg viewBox="0 0 320 290" class="w-full max-w-[320px] h-auto mx-auto select-none" role="img" aria-label="Biểu đồ Radar so sánh 5 chiều hương vị">
      ${rings}
      ${spokes}
      ${polygons}
    </svg>
  `;
}


