function getTk123TrainingRules() {
  try {
    const raw = localStorage.getItem(STORAGE_TK123_TRAINING_KEY);
    if (!raw) return DEFAULT_TK123_TRAINING_RULES;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.length > 0 ? parsed : DEFAULT_TK123_TRAINING_RULES;
  } catch (e) {
    return DEFAULT_TK123_TRAINING_RULES;
  }
}

function saveTk123TrainingRules(rules) {
  try {
    localStorage.setItem(STORAGE_TK123_TRAINING_KEY, JSON.stringify(rules));
  } catch (e) {}
}

function formatAiReplyHtml(rawText) {
  const safe = String(rawText || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\*\*([^*]+)\*\*/g, '<strong class="text-[#0F4C3A] font-extrabold">$1</strong>')
    .replace(/\*([^*]+)\*/g, '<em>$1</em>')
    .replace(/\n/g, "<br/>");
  return safe;
}

function buildKhmerCakesSystemPrompt(dishesData) {
  const briefList = dishesData
    .map(
      (d) =>
        `${d.id}. ${d.name} (Mã ${d.qrCodeId}, ${cleanCategoryLabel(d.categoryName)}): Xuất xứ: ${d.originExact} Cách làm: ${d.recipeExact} Nguyên liệu (${d.baseBatch} ${d.batchUnit || "phần"}, ~${formatVndCurrency(d.estimatedCostPerBaseBatch)}): ${d.ingredients.map((i) => i.item + " " + i.amount).join(", ")}. Thời gian: ${d.prepTime}. Bảo quản: ${d.shelfLife}.`
    )
    .join("\n");

  const customRules = getTk123TrainingRules()
    .map((r) => `- Khi hỏi về [${r.keywords}]: ${r.answer}`)
    .join("\n");

  return (
    "Bạn tên là 'Trường Khánh', Trợ lý Trường Khánh thông minh của website 'Bảo Tồn Bánh Truyền Thống Khmer Vĩnh Long'. " +
    "Khi xưng hô, hãy tự xưng là 'Trường Khánh' (hoặc 'mình') và gọi người dùng là 'bạn'. " +
    "Hãy trả lời chính xác, gần gũi, dễ hiểu bằng tiếng Việt giao tiếp thông dụng (ngắn gọn khoảng 3-6 câu, trình bày rõ ràng). " +
    "Dưới đây là thông tin chi tiết về các món bánh truyền thống Khmer tại 3 khu vực Trà Vinh, Vĩnh Long và Bến Tre:\n" +
    briefList +
    "\n\nCâu hỏi thường gặp bổ sung:\n" +
    customRules
  );
}

