  function renderCreativeTasteLabSection() {
    if (!creativeLabContainer) return;
    const moods = window.TASTE_MOOD_PRESETS || [];
    const pigments = window.NATURAL_PIGMENTS_LAB || [];
    const matchPairs = window.KHMER_NAME_MATCH_PAIRS || [];

    const activeMood = moods.find((m) => m.id === activeMoodId) || moods[0];
    const moodDishes = data.filter((d) => activeMood.dishIds.includes(d.id));
    const wheelDish = data.find((d) => d.id === wheelPickedDishId) || data[0];
    const activePigment = pigments.find((p) => p.id === activePigmentId) || pigments[0];
    const pigmentDishes = data.filter((d) => activePigment.dishIds.includes(d.id));

    const sliceColors = ["#0D7A5F", "#D97706", "#B91C1C", "#047857", "#B45309", "#0F4C5C", "#15803D"];
    const totalSlices = data.length;
    const wheelSlicesSvg = data
      .map((item, i) => {
        const startAngle = (i * 2 * Math.PI) / totalSlices - Math.PI / 2;
        const endAngle = ((i + 1) * 2 * Math.PI) / totalSlices - Math.PI / 2;
        const midAngle = (startAngle + endAngle) / 2;
        const r = 118;
        const cx = 130;
        const cy = 130;
        const x1 = cx + r * Math.cos(startAngle);
        const y1 = cy + r * Math.sin(startAngle);
        const x2 = cx + r * Math.cos(endAngle);
        const y2 = cy + r * Math.sin(endAngle);
        const tx = cx + r * 0.68 * Math.cos(midAngle);
        const ty = cy + r * 0.68 * Math.sin(midAngle);
        const deg = (midAngle * 180) / Math.PI;
        const col = sliceColors[i % sliceColors.length];
        return `
          <path d="M ${cx},${cy} L ${x1.toFixed(1)},${y1.toFixed(1)} A ${r},${r} 0 0,1 ${x2.toFixed(1)},${y2.toFixed(1)} Z" fill="${col}" stroke="#FFFDF8" stroke-width="1.5" />
          <text x="${tx.toFixed(1)}" y="${ty.toFixed(1)}" fill="#FEF3C7" font-size="8.5" font-weight="900" text-anchor="middle" dominant-baseline="middle" transform="rotate(${deg.toFixed(1)} ${tx.toFixed(1)} ${ty.toFixed(1)})">#${item.id}</text>
        `;
      })
      .join("");

    creativeLabContainer.innerHTML = `
      <div class="pop-card bg-gradient-to-br from-[#FFFDF9] via-[#FEF6E4] to-[#ECFDF5] rounded-3xl p-4 md:p-6 mb-7 border border-[#C8922A]/60">
        <div class="flex flex-col lg:flex-row lg:items-center justify-between gap-3 pb-4 border-b border-dashed border-amber-400/70">
          <div>
            <span class="inline-flex items-center gap-1.5 bg-[#0F4C3A] text-amber-200 px-3 py-0.5 rounded-full text-[11px] font-extrabold mb-1">
              <i class="fa-solid fa-wand-magic-sparkles text-amber-300"></i> Khám Phá &amp; Trò Chơi
            </span>
            <h2 class="font-serif-heritage text-xl md:text-2xl font-bold text-[#0F4C3A]">
              Chọn Bánh Theo Sở Thích &amp; Xem Màu Tự Nhiên
            </h2>
          </div>

          <div class="flex items-center gap-1 bg-white/90 p-1 rounded-2xl border border-[#C8922A]/50 flex-wrap">
            <button
              type="button"
              data-lab-tab="wheel"
              class="lab-tab-btn px-3 py-1.5 rounded-xl text-xs font-extrabold transition-all flex items-center gap-1.5 ${
                creativeLabTab === "wheel"
                  ? "bg-[#0F4C3A] text-amber-200 shadow-sm"
                  : "text-stone-700 hover:bg-amber-100/70"
              }"
            >
              <i class="fa-solid fa-dice text-amber-400"></i>
              <span>Chọn Theo Sở Thích</span>
            </button>
            <button
              type="button"
              data-lab-tab="pigment"
              class="lab-tab-btn px-3 py-1.5 rounded-xl text-xs font-extrabold transition-all flex items-center gap-1.5 ${
                creativeLabTab === "pigment"
                  ? "bg-[#0F4C3A] text-amber-200 shadow-sm"
                  : "text-stone-700 hover:bg-amber-100/70"
              }"
            >
              <i class="fa-solid fa-palette text-emerald-500"></i>
              <span>6 Màu Tự Nhiên Từ Lá Cây</span>
            </button>
            <button
              type="button"
              data-lab-tab="matchgame"
              class="lab-tab-btn px-3 py-1.5 rounded-xl text-xs font-extrabold transition-all flex items-center gap-1.5 ${
                creativeLabTab === "matchgame"
                  ? "bg-[#0F4C3A] text-amber-200 shadow-sm"
                  : "text-stone-700 hover:bg-amber-100/70"
              }"
            >
              <i class="fa-solid fa-puzzle-piece text-rose-500"></i>
              <span>Trò Chơi Ghép Tên (${matchSolvedDishIds.length}/6)</span>
            </button>
            <button
              type="button"
              data-lab-tab="alchemy"
              class="lab-tab-btn px-3 py-1.5 rounded-xl text-xs font-extrabold transition-all flex items-center gap-1.5 ${
                creativeLabTab === "alchemy"
                  ? "bg-[#0F4C3A] text-amber-200 shadow-sm"
                  : "text-stone-700 hover:bg-amber-100/70"
              }"
            >
              <i class="fa-solid fa-flask text-amber-500"></i>
              <span>Phòng Phối Bột &amp; Pha Màu</span>
            </button>
          </div>
        </div>

        ${
          creativeLabTab === "wheel"
            ? `
          <div class="grid grid-cols-1 lg:grid-cols-12 gap-5 mt-4 items-center">
            <!-- Cột Trái: Chọn Gu Nhanh -->
            <div class="lg:col-span-7 space-y-3">
              <div class="flex items-center justify-between gap-2 flex-wrap">
                <p class="text-xs font-extrabold uppercase tracking-wider text-rose-700">
                  <i class="fa-solid fa-heart-pulse mr-1"></i>Hôm nay bạn thèm hương vị nào?
                </p>
                <span class="text-[11px] font-semibold text-stone-600">Chạm để lọc theo cảm hứng</span>
              </div>

              <div class="flex items-center gap-1.5 flex-wrap">
                ${moods
                  .map(
                    (m) => `
                  <button
                    type="button"
                    data-mood-btn="${m.id}"
                    class="mood-select-btn px-3 py-1.5 rounded-xl text-xs font-extrabold border transition-all flex items-center gap-1.5 ${
                      m.id === activeMood.id
                        ? "bg-[#0F4C3A] text-amber-200 border-[#C8922A] shadow-sm"
                        : "bg-white text-stone-800 border-stone-300 hover:bg-amber-50"
                    }"
                  >
                    <i class="fa-solid ${m.icon} text-amber-500"></i>
                    <span>${m.label}</span>
                  </button>
                `
                  )
                  .join("")}
              </div>

              <div class="bg-white/95 rounded-2xl p-3.5 border border-[#C8922A]/45">
                <p class="text-xs font-bold text-stone-700 mb-2.5">
                  <i class="fa-solid fa-sparkles text-amber-500 mr-1"></i>${activeMood.desc}:
                </p>
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  ${moodDishes
                    .slice(0, 4)
                    .map(
                      (d) => `
                    <div class="p-2.5 rounded-xl bg-[#FAF6EE] border border-stone-200 flex items-center justify-between gap-2 hover:border-amber-400 transition-all">
                      <div class="flex items-center gap-2.5 min-w-0">
                        <img src="${d.image}" alt="${d.name}" class="w-11 h-11 rounded-xl object-cover border border-stone-300 shrink-0" />
                        <div class="min-w-0">
                          <span class="text-[10px] font-bold text-rose-700">${cleanCategoryLabel(d.categoryName)}</span>
                          <h4 class="text-xs font-extrabold text-[#0F4C3A] truncate">${d.id}. ${d.name}</h4>
                          <p class="text-[10px] text-stone-500 truncate">${d.prepTime}</p>
                        </div>
                      </div>
                      <button type="button" data-lab-open-dish="${d.id}" class="lab-open-dish-btn px-2.5 py-1.5 rounded-lg bg-[#0F4C3A] text-amber-200 text-[10px] font-extrabold shrink-0">
                        Mở
                      </button>
                    </div>
                  `
                    )
                    .join("")}
                </div>
              </div>
            </div>

            <!-- Cột Phải: Vòng Quay Chọn Bánh Ngẫu Nhiên -->
            <div class="lg:col-span-5 bg-white rounded-3xl p-4 border-2 border-[#C8922A]/60 shadow-sm text-center">
              <div class="flex items-center justify-between gap-2 mb-2">
                <span class="text-[11px] font-extrabold uppercase tracking-wider text-[#0F4C3A]">
                  <i class="fa-solid fa-dharmachakra text-amber-600 mr-1"></i>Vòng Quay Chọn Bánh
                </span>
                <button
                  type="button"
                  id="spin-wheel-action-btn"
                  class="shimmer-btn pop-btn bg-rose-700 hover:bg-rose-800 text-amber-100 text-xs font-extrabold px-3.5 py-1.5 rounded-xl flex items-center gap-1.5"
                >
                  <i class="fa-solid fa-rotate"></i>
                  <span>Quay Ngay!</span>
                </button>
              </div>

              <div class="relative w-52 h-52 mx-auto my-2 flex items-center justify-center">
                <div class="absolute -top-2 left-1/2 -translate-x-1/2 z-10 text-rose-700 text-xl drop-shadow">
                  <i class="fa-solid fa-caret-down"></i>
                </div>
                <svg viewBox="0 0 260 260" class="w-full h-full drop-shadow-md">
                  <g id="lucky-wheel-svg-group" class="wheel-spin-transition" style="transform: rotate(${wheelCurrentRotation}deg)">
                    ${wheelSlicesSvg}
                  </g>
                  <circle cx="130" cy="130" r="26" fill="#FFFDF8" stroke="#C8922A" stroke-width="3" />
                  <text x="130" y="133" text-anchor="middle" fill="#0F4C3A" font-size="9.5" font-weight="900">QUAY</text>
                </svg>
              </div>

              <div class="p-3 rounded-2xl bg-[#FAF6EE] border border-amber-300 text-left flex items-center justify-between gap-2.5 mt-2">
                <div class="flex items-center gap-2.5 min-w-0">
                  <img src="${wheelDish.image}" alt="${wheelDish.name}" class="w-12 h-12 rounded-xl object-cover border border-amber-400 shrink-0" />
                  <div class="min-w-0">
                    <span class="text-[10px] font-extrabold uppercase text-rose-700">Gợi ý hôm nay (#${wheelDish.id})</span>
                    <h4 class="text-xs md:text-sm font-extrabold text-[#0F4C3A] truncate">${wheelDish.name}</h4>
                    <p class="text-[11px] text-stone-600 truncate">${wheelDish.coreSummary}</p>
                  </div>
                </div>
                <div class="flex items-center gap-1 shrink-0">
                  <button type="button" data-lab-open-dish="${wheelDish.id}" class="lab-open-dish-btn px-2.5 py-1.5 rounded-xl bg-[#0F4C3A] text-amber-200 text-[11px] font-extrabold">
                    Xem
                  </button>
                  <button type="button" data-lab-cook-dish="${wheelDish.id}" class="lab-cook-dish-btn px-2.5 py-1.5 rounded-xl bg-amber-300 text-stone-900 text-[11px] font-extrabold" title="Vào bếp">
                    <i class="fa-solid fa-fire-burner text-rose-700"></i>
                  </button>
                </div>
              </div>
            </div>
          </div>
        `
            : creativeLabTab === "pigment"
            ? `
          <div class="grid grid-cols-1 lg:grid-cols-12 gap-4 mt-4 items-stretch">
            <div class="lg:col-span-6 grid grid-cols-2 sm:grid-cols-3 gap-2.5">
              ${pigments
                .map((pig) => {
                  const isAct = pig.id === activePigment.id;
                  return `
                    <button
                      type="button"
                      data-pigment-id="${pig.id}"
                      class="pigment-swatch-card text-left p-3 rounded-2xl border transition-all flex flex-col justify-between ${
                        isAct
                          ? "bg-white border-2 border-[#0F4C3A] shadow-md"
                          : "bg-white/85 border-stone-200 hover:bg-white"
                      }"
                    >
                      <div class="flex items-center justify-between gap-2 mb-2">
                        <span class="w-8 h-8 rounded-full border-2 border-white shadow-md flex items-center justify-center text-white text-xs" style="background-color: ${pig.hex}">
                          <i class="fa-solid ${pig.icon}"></i>
                        </span>
                        <span class="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-stone-100 text-stone-700">Màu tự nhiên</span>
                      </div>
                      <div>
                        <p class="text-xs font-extrabold text-stone-900 leading-tight">${pig.plantName}</p>
                        <p class="text-[10px] font-bold mt-0.5" style="color: ${pig.hex}">${pig.colorName}</p>
                      </div>
                    </button>
                  `;
                })
                .join("")}
            </div>

            <div class="pigment-detail-box lg:col-span-6 rounded-2xl p-4 md:p-5 border border-[#C8922A]/60 flex flex-col justify-between" style="background: ${activePigment.softBg}">
              <div>
                <div class="flex items-center justify-between gap-2 flex-wrap mb-2">
                  <span class="px-3 py-1 rounded-full text-white text-[11px] font-extrabold shadow-sm" style="background-color: ${activePigment.hex}">
                    <i class="fa-solid ${activePigment.icon} mr-1"></i>${activePigment.colorName}
                  </span>
                  <span class="text-[11px] font-extrabold text-stone-700 bg-white/80 px-2.5 py-0.5 rounded-full border border-stone-300">
                    ${activePigment.regionTag}
                  </span>
                </div>
                <h3 class="font-serif-heritage text-lg md:text-xl font-bold text-stone-900">${activePigment.plantName}</h3>
                <p class="text-xs text-stone-800 leading-relaxed bg-white/90 p-3 rounded-xl border border-stone-200/80 my-2.5">
                  <strong class="text-[#0F4C3A]"><i class="fa-solid fa-flask mr-1"></i>Cách lấy màu tự nhiên:</strong> ${activePigment.alchemySecret}
                </p>
                <p class="text-xs font-bold text-stone-800 mb-2">
                  <i class="fa-solid fa-wind text-rose-700 mr-1"></i>Hương vị đặc trưng: <span class="font-normal">${activePigment.aromaNote}</span>
                </p>
              </div>

              <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-2 border-t border-stone-300/60">
                ${pigmentDishes
                  .map(
                    (d) => `
                  <button
                    type="button"
                    data-lab-open-dish="${d.id}"
                    class="lab-open-dish-btn bg-white hover:bg-amber-50 p-2 rounded-xl border border-stone-300 flex items-center justify-between gap-2 text-left"
                  >
                    <div class="flex items-center gap-2 min-w-0">
                      <img src="${d.image}" alt="${d.name}" class="w-9 h-9 rounded-lg object-cover shrink-0" />
                      <div class="min-w-0">
                        <p class="text-xs font-extrabold text-[#0F4C3A] truncate">${d.name}</p>
                        <p class="text-[10px] text-stone-500 truncate">${cleanCategoryLabel(d.categoryName)}</p>
                      </div>
                    </div>
                    <i class="fa-solid fa-arrow-right text-xs text-rose-700 shrink-0"></i>
                  </button>
                `
                  )
                  .join("")}
              </div>
            </div>
          </div>
        `
            : creativeLabTab === "alchemy"
            ? (() => {
                const comboMap = {
                  "la-bu-ngot": { dishId: 1, hex: "#0D7A5F", colorName: "Xanh Ngọc Bích Bền Lửa", reaction: "Nước cốt lá bù ngót già quyện vào hạt nếp sáp rặt đã gút ráo, giữ màu xanh ngọc óng ánh suốt 10–12 tiếng luộc rền." },
                  "la-dua": { dishId: 2, hex: "#16A34A", colorName: "Xanh Cốm Đồng Nội", reaction: "Tinh dầu lá dứa tươi thấm vào bột gạo/bột năng tạo sắc xanh non mát mắt và hương thơm bốc lên ngay khi hấp hoặc ép rổ nước đá." },
                  "la-mo": { dishId: 12, hex: "#1E293B", colorName: "Đen Bóng Thảo Mộc", reaction: "Lá mơ lông xay vắt nước xanh sẫm, khi nhồi bột ốp lên lá mít đem hấp gặp nhiệt độ cao sẽ chuyển sang sắc đen bóng giòn dai sần sật." },
                  "thot-not": { dishId: 3, hex: "#D97706", colorName: "Vàng Hổ Phách Rễ Tre", reaction: "Đường thốt nốt thắng ấm lên men cùng bột gạo tẻ tạo cấu trúc rễ tre xốp mềm và sắc vàng nâu óng ả." },
                  "lua-non": { dishId: 7, hex: "#65A30D", colorName: "Xanh Sữa Lúa Nếp Non", reaction: "Hạt lúa nếp non đầu mùa rang trên nồi đất, giã tay trong cối gỗ rồi ủ ngấm nước cốt dừa tươi tạo độ dẻo thơm thanh khiết." },
                  "chuoi-dua": { dishId: 13, hex: "#BE123C", colorName: "Đỏ Hồng Mật Chuối & Nắng Dừa", reaction: "Nhân chuối xiêm chín được bao bọc bởi nếp cốt dừa đậu đen trong ống đọt lá dừa nước quấn lò xo, khi luộc rền tươm mật đỏ hồng." }
                };
                const res = comboMap[alchemyColorId] || comboMap["la-bu-ngot"];
                const matchedCake = data.find((d) => d.id === res.dishId) || data[0];
                return `
                  <div class="mt-4 bg-white rounded-2xl p-4 md:p-5 border border-[#C8922A]/55 grid grid-cols-1 lg:grid-cols-12 gap-5 items-center">
                    <div class="lg:col-span-6 space-y-3">
                      <span class="text-[10px] font-extrabold uppercase text-emerald-800">
                        <i class="fa-solid fa-mortar-pestle mr-1"></i>Mô phỏng cối giã &amp; phối màu thảo mộc Khmer
                      </span>
                      <h3 class="font-serif-heritage text-lg md:text-xl font-bold text-[#0F4C3A]">
                        Chọn Nguyên Liệu Thảo Mộc Để Xem Phản Ứng Tạo Màu Bánh
                      </h3>
                      <div class="grid grid-cols-2 sm:grid-cols-3 gap-2">
                        ${[
                          { id: "la-bu-ngot", name: "Lá Bù Ngót Tươi", sub: "Nếp sáp rặt", hex: "#0D7A5F" },
                          { id: "la-dua", name: "Lá Dứa Đồng Nội", sub: "Bột gạo / Bột năng", hex: "#16A34A" },
                          { id: "la-mo", name: "Lá Mơ Lông", sub: "Ốp lá mít hấp", hex: "#1E293B" },
                          { id: "thot-not", name: "Đường Thốt Nốt", sub: "Ủ men rễ tre", hex: "#D97706" },
                          { id: "lua-non", name: "Lúa Nếp Non", sub: "Rang nồi đất giã cối", hex: "#65A30D" },
                          { id: "chuoi-dua", name: "Chuối Xiêm & Lá Dừa", sub: "Quấn ống lò xo", hex: "#BE123C" }
                        ]
                          .map(
                            (item) => `
                          <button
                            type="button"
                            data-alchemy-color="${item.id}"
                            class="alchemy-color-btn p-2.5 rounded-xl border text-left transition-all ${
                              alchemyColorId === item.id
                                ? "bg-[#0F4C3A] text-amber-200 border-[#C8922A] shadow-md"
                                : "bg-[#FAF6EE] hover:bg-amber-50 text-stone-800 border-stone-300"
                            }"
                          >
                            <div class="flex items-center gap-1.5 mb-0.5">
                              <span class="w-3.5 h-3.5 rounded-full border border-white shrink-0" style="background-color: ${item.hex}"></span>
                              <span class="text-xs font-extrabold truncate">${item.name}</span>
                            </div>
                            <span class="text-[10px] opacity-80 block truncate">${item.sub}</span>
                          </button>
                        `
                          )
                          .join("")}
                      </div>
                    </div>

                    <div class="lg:col-span-6 p-4 rounded-2xl bg-[#FAF6EE] border-2 border-[#C8922A] flex flex-col sm:flex-row items-center gap-4">
                      <div class="w-28 h-28 rounded-full border-4 border-white shadow-lg flex flex-col items-center justify-center text-white text-center p-2 shrink-0" style="background-color: ${res.hex}">
                        <i class="fa-solid fa-bowl-rice text-xl mb-1"></i>
                        <span class="text-[10px] font-extrabold leading-tight">${res.colorName}</span>
                      </div>
                      <div class="space-y-1.5 text-left">
                        <span class="px-2 py-0.5 rounded bg-amber-200 text-stone-900 text-[10px] font-extrabold">
                          Món bánh tạo thành: ${matchedCake.qrCodeId} — ${matchedCake.name}
                        </span>
                        <h4 class="text-sm md:text-base font-extrabold text-[#0F4C3A]">${matchedCake.name} (${matchedCake.khmerName})</h4>
                        <p class="text-xs text-stone-700 leading-relaxed">${res.reaction}</p>
                        <div class="pt-1.5 flex items-center gap-2 flex-wrap">
                          <button type="button" data-lab-open-dish="${matchedCake.id}" class="lab-open-dish-btn px-3 py-1.5 rounded-xl bg-[#0F4C3A] text-amber-200 text-xs font-extrabold">
                            Mở trang ${matchedCake.name}
                          </button>
                          <button type="button" data-lab-cook-dish="${matchedCake.id}" class="lab-cook-dish-btn px-3 py-1.5 rounded-xl bg-amber-300 text-stone-900 text-xs font-extrabold">
                            Vào Bếp làm thử
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                `;
              })()
                        : `
          <!-- Mini-Game Ghép Tên Bánh Khmer & Đặc Trưng -->
          <div class="mt-4 bg-white rounded-2xl p-4 md:p-5 border border-[#C8922A]/50">
            <div class="flex items-center justify-between gap-2 flex-wrap mb-3">
              <div>
                <h3 class="text-sm md:text-base font-extrabold text-[#0F4C3A]">
                  <i class="fa-solid fa-gamepad text-rose-700 mr-1.5"></i>Trò Chơi Ghép Tên Tiếng Khmer Của 6 Món Bánh
                </h3>
                <p class="text-xs text-stone-600">Bước 1: Chọn tên gọi Khmer bên trái • Bước 2: Chạm vào đúng món bánh tương ứng bên phải!</p>
              </div>
              <div class="flex items-center gap-2">
                <span class="px-3 py-1 rounded-xl bg-amber-100 text-stone-900 font-extrabold text-xs border border-amber-300">
                  Đã ghép đúng: <strong class="text-rose-700">${matchSolvedDishIds.length}/${matchPairs.length}</strong>
                </span>
                <button type="button" id="reset-match-game-btn" class="px-2.5 py-1 rounded-xl bg-stone-100 hover:bg-stone-200 text-stone-700 text-xs font-bold">
                  Chơi lại
                </button>
              </div>
            </div>

            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div class="space-y-2">
                <p class="text-[11px] font-extrabold uppercase text-stone-500">1. Tên gọi tiếng Khmer</p>
                ${matchPairs
                  .map((pair) => {
                    const solved = matchSolvedDishIds.includes(pair.dishId);
                    const isSelected = matchSelectedKhmer === pair.dishId;
                    return `
                      <button
                        type="button"
                        data-match-khmer="${pair.dishId}"
                        ${solved ? "disabled" : ""}
                        class="match-khmer-btn w-full text-left p-3 rounded-xl border text-xs font-extrabold flex items-center justify-between transition-all ${
                          solved
                            ? "bg-emerald-50 border-emerald-400 text-emerald-900"
                            : isSelected
                            ? "bg-[#0F4C3A] text-amber-200 border-[#C8922A] shadow-md"
                            : "bg-[#FAF6EE] hover:bg-amber-50 text-stone-900 border-stone-300"
                        }"
                      >
                        <span><i class="fa-solid ${solved ? "fa-circle-check text-emerald-600" : "fa-tag text-rose-700"} mr-2"></i>${pair.khmer}</span>
                        <span class="text-[10px] font-bold ${solved ? "text-emerald-700" : isSelected ? "text-amber-300" : "text-stone-500"}">
                          ${solved ? "Đã ghép chuẩn" : isSelected ? "Đang chọn..." : "Chạm để chọn"}
                        </span>
                      </button>
                    `;
                  })
                  .join("")}
              </div>

              <div class="space-y-2">
                <p class="text-[11px] font-extrabold uppercase text-stone-500">2. Món bánh &amp; Kỹ thuật đặc trưng</p>
                ${[matchPairs[2], matchPairs[0], matchPairs[4], matchPairs[1], matchPairs[5], matchPairs[3]]
                  .map((pair) => {
                    const solved = matchSolvedDishIds.includes(pair.dishId);
                    const cake = data.find((d) => d.id === pair.dishId) || data[0];
                    return `
                      <button
                        type="button"
                        data-match-viet="${pair.dishId}"
                        class="match-viet-btn w-full text-left p-2.5 rounded-xl border text-xs font-bold flex items-center justify-between gap-2 transition-all ${
                          solved
                            ? "bg-emerald-700 text-white border-emerald-800"
                            : "bg-white hover:bg-amber-50 text-stone-800 border-stone-300"
                        }"
                      >
                        <div class="flex items-center gap-2.5 min-w-0">
                          <img src="${cake.image}" alt="" class="w-9 h-9 rounded-lg object-cover shrink-0" />
                          <span class="truncate">${pair.viet}</span>
                        </div>
                        <span class="text-[10px] font-extrabold shrink-0 ${solved ? "text-amber-200" : "text-[#0F4C3A]"}">
                          ${solved ? pair.khmer : "Ghép vào đây"}
                        </span>
                      </button>
                    `;
                  })
                  .join("")}
              </div>
            </div>
          </div>
        `
        }
      </div>
    `;

    creativeLabContainer.querySelectorAll(".lab-tab-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        creativeLabTab = btn.getAttribute("data-lab-tab") || "wheel";
        renderCreativeTasteLabSection();
      });
    });

    creativeLabContainer.querySelectorAll(".mood-select-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        activeMoodId = btn.getAttribute("data-mood-btn") || "crispy";
        renderCreativeTasteLabSection();
      });
    });

    creativeLabContainer.querySelectorAll(".pigment-swatch-card").forEach((btn) => {
      btn.addEventListener("click", () => {
        activePigmentId = btn.getAttribute("data-pigment-id") || "la-bu-ngot";
        renderCreativeTasteLabSection();
      });
    });

    creativeLabContainer.querySelectorAll(".lab-open-dish-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        navigateToSpoke(parseInt(btn.getAttribute("data-lab-open-dish"), 10));
      });
    });

    creativeLabContainer.querySelectorAll(".lab-cook-dish-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        openCookingWizardModal(parseInt(btn.getAttribute("data-lab-cook-dish"), 10), 0);
      });
    });

    const spinBtn = document.getElementById("spin-wheel-action-btn");
    spinBtn?.addEventListener("click", () => {
      if (isWheelSpinning) return;
      isWheelSpinning = true;
      const nextDish = data[Math.floor(Math.random() * data.length)] || data[0];
      wheelPickedDishId = nextDish.id;
      wheelCurrentRotation += 1080 + Math.floor(Math.random() * 360);
      const wheelGroup = document.getElementById("lucky-wheel-svg-group");
      if (wheelGroup) {
        wheelGroup.style.transform = `rotate(${wheelCurrentRotation}deg)`;
      }
      setTimeout(() => {
        isWheelSpinning = false;
        playKitchenBellChime();
        triggerCelebrationConfetti();
        renderCreativeTasteLabSection();
        showAppToast(`Vòng quay chọn món: #${nextDish.id} ${nextDish.name}!`);
      }, 3200);
    });

    creativeLabContainer.querySelectorAll(".match-khmer-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        matchSelectedKhmer = parseInt(btn.getAttribute("data-match-khmer"), 10);
        renderCreativeTasteLabSection();
      });
    });

    creativeLabContainer.querySelectorAll(".match-viet-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const targetDishId = parseInt(btn.getAttribute("data-match-viet"), 10);
        if (matchSolvedDishIds.includes(targetDishId)) {
          navigateToSpoke(targetDishId);
          return;
        }
        if (!matchSelectedKhmer) {
          showAppToast("Hãy chạm chọn 1 tên bánh tiếng Khmer ở cột bên trái trước nhé!");
          return;
        }
        if (matchSelectedKhmer === targetDishId) {
          matchSolvedDishIds.push(targetDishId);
          matchSelectedKhmer = null;
          playKitchenBellChime();
          if (matchSolvedDishIds.length === matchPairs.length) {
            triggerCelebrationConfetti();
            showAppToast("Xuất sắc! Bạn đã ghép đúng cả 6 tên bánh tiếng Khmer!");
          } else {
            showAppToast("Chính xác! Tiếp tục ghép cặp tiếp theo nhé!");
          }
          renderCreativeTasteLabSection();
        } else {
          showAppToast("Chưa khớp rồi, bạn thử chọn món bánh khác nhé!");
        }
      });
    });

    creativeLabContainer.querySelectorAll(".alchemy-color-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        alchemyColorId = btn.getAttribute("data-alchemy-color") || "la-bu-ngot";
        playKitchenBellChime();
        renderCreativeTasteLabSection();
      });
    });

    document.getElementById("reset-match-game-btn")?.addEventListener("click", () => {
      matchSolvedDishIds = [];
      matchSelectedKhmer = null;
      renderCreativeTasteLabSection();
    });
  }

  function clearWizardTimer() {
    if (wizardTimerInterval) {
      clearInterval(wizardTimerInterval);
      wizardTimerInterval = null;
    }
  }

  function openCookingWizardModal(defaultCakeId = 1, initialStepIdx = 0) {
    if (!cookingWizardModal || !cookingWizardBody) return;
    clearWizardTimer();
    cookingWizardModal.classList.remove("hidden");

    let currentCakeId = parseInt(defaultCakeId, 10) || 1;
    let stepIdx = parseInt(initialStepIdx, 10) || 0;
    let showIngredientsDrawer = false;
    let timerRemaining = 0;
    let timerRunning = false;

    const renderWizard = () => {
      clearWizardTimer();
      timerRunning = false;
      const cake = data.find((d) => d.id === currentCakeId) || data[0];
      const steps = cake.steps || [];
      if (stepIdx < 0) stepIdx = 0;
      if (stepIdx >= steps.length) stepIdx = steps.length - 1;
      const curStep = steps[stepIdx] || { stepNumber: 1, title: "Chuẩn bị", duration: "15 phút", detail: cake.recipeExact, timerSeconds: 900 };
      timerRemaining = curStep.timerSeconds || 900;
      const progressPct = Math.round(((stepIdx + 1) / Math.max(steps.length, 1)) * 100);

      cookingWizardBody.innerHTML = `
        <div class="flex items-center gap-3 pb-3 border-b border-stone-200 pr-10">
          <img src="${BRAND_ICONS.kitchenFestival}" alt="Trợ lý Vào Bếp" class="w-12 h-12 rounded-full object-cover logo-emblem-ring shrink-0" />
          <div class="min-w-0 flex-1">
            <span class="text-[10px] font-extrabold uppercase tracking-wider text-rose-700 block">
              <i class="fa-solid fa-fire-burner mr-1"></i>Hướng Dẫn Làm Bánh Từng Bước
            </span>
            <select id="wizard-cake-select" class="mt-0.5 w-full sm:w-auto px-2.5 py-1 rounded-xl bg-amber-50 border border-[#C8922A]/60 text-xs md:text-sm font-extrabold text-[#0F4C3A]">
              ${data
                .map(
                  (d) => `
                <option value="${d.id}" ${d.id === cake.id ? "selected" : ""}>
                  ${d.id}. ${d.name} (${d.prepTime})
                </option>
              `
                )
                .join("")}
            </select>
          </div>
        </div>

        <div class="my-3">
          <div class="flex items-center justify-between text-xs font-bold text-stone-700 mb-1.5">
            <span>Tiến độ: <strong class="text-[#0F4C3A]">Bước ${stepIdx + 1} / ${steps.length}</strong></span>
            <span class="text-rose-700 font-extrabold">${progressPct}% hoàn thành</span>
          </div>
          <div class="w-full h-2.5 rounded-full bg-stone-200 overflow-hidden">
            <div class="h-full rounded-full bg-gradient-to-r from-[#0F4C3A] via-emerald-600 to-amber-500 transition-all duration-300" style="width: ${progressPct}%"></div>
          </div>
          <div class="flex items-center gap-1.5 mt-2 overflow-x-auto no-scrollbar pb-1">
            ${steps
              .map(
                (st, idx) => `
              <button
                type="button"
                data-wizard-step-pill="${idx}"
                class="wizard-step-pill shrink-0 px-2.5 py-1 rounded-xl text-[11px] font-bold border transition-all ${
                  idx === stepIdx
                    ? "bg-[#0F4C3A] text-amber-200 border-[#C8922A] font-extrabold"
                    : idx < stepIdx
                    ? "bg-emerald-100 text-emerald-900 border-emerald-300"
                    : "bg-white text-stone-600 border-stone-300"
                }"
              >
                ${idx < stepIdx ? '<i class="fa-solid fa-check mr-1"></i>' : ""}Bước ${st.stepNumber}
              </button>
            `
              )
              .join("")}
          </div>
        </div>

        <div class="p-4 md:p-5 rounded-2xl bg-white border-2 border-[#C8922A]/60 shadow-sm my-3">
          <div class="flex items-center justify-between gap-2 flex-wrap mb-2">
            <span class="px-3 py-1 rounded-xl bg-[#0F4C3A] text-amber-200 text-xs font-extrabold">
              Bước ${curStep.stepNumber}: ${curStep.title}
            </span>
            <span class="px-2.5 py-1 rounded-xl bg-amber-100 text-stone-900 text-xs font-bold border border-amber-300">
              <i class="fa-regular fa-clock text-rose-700 mr-1"></i>${curStep.duration}
            </span>
          </div>

          <p class="text-sm md:text-base text-stone-800 font-medium leading-relaxed my-3">
            ${curStep.detail}
          </p>

          <!-- Đồng hồ hẹn giờ thông minh ngay trong bước -->
          <div class="p-3.5 rounded-2xl bg-[#FAF6EE] border border-[#C8922A]/50 flex flex-col sm:flex-row sm:items-center justify-between gap-3 mt-3">
            <div class="flex items-center gap-3">
              <div class="w-11 h-11 rounded-2xl bg-[#0F4C3A] text-amber-300 flex items-center justify-center text-lg shrink-0">
                <i class="fa-solid fa-stopwatch"></i>
              </div>
              <div>
                <p id="wizard-timer-status" class="text-[10px] font-extrabold uppercase tracking-wider text-rose-700">HẸN GIỜ CÔNG ĐOẠN NÀY</p>
                <p id="wizard-timer-display" class="text-xl md:text-2xl font-black font-mono text-stone-900">${formatCountdownTime(timerRemaining)}</p>
              </div>
            </div>
            <div class="flex items-center gap-1.5 flex-wrap">
              <button type="button" id="wizard-timer-minus-btn" class="px-2.5 py-1.5 rounded-xl bg-white hover:bg-stone-100 border border-stone-300 text-xs font-bold text-stone-700" title="Giảm 1 phút">-1p</button>
              <button type="button" id="wizard-timer-plus-btn" class="px-2.5 py-1.5 rounded-xl bg-white hover:bg-stone-100 border border-stone-300 text-xs font-bold text-stone-700" title="Tăng 1 phút">+1p</button>
              <button type="button" id="wizard-timer-toggle-btn" class="pop-btn bg-[#0F4C3A] hover:bg-[#093528] text-amber-200 text-xs font-extrabold px-3.5 py-2 rounded-xl flex items-center gap-1.5">
                <i class="fa-solid fa-play"></i>
                <span id="wizard-timer-toggle-label">Bắt đầu đếm</span>
              </button>
              <button type="button" id="wizard-speak-step-btn" class="pop-btn bg-amber-300 hover:bg-amber-400 text-stone-900 text-xs font-extrabold px-3 py-2 rounded-xl flex items-center gap-1.5">
                <i class="fa-solid fa-volume-high text-rose-700"></i>
                <span>Đọc bước này</span>
              </button>
            </div>
          </div>
        </div>

        <div class="mb-3">
          <button
            type="button"
            id="wizard-toggle-ing-btn"
            class="text-xs font-extrabold text-[#0F4C3A] hover:underline flex items-center gap-1.5"
          >
            <i class="fa-solid fa-basket-shopping text-rose-700"></i>
            <span>${showIngredientsDrawer ? "Ẩn danh sách nguyên liệu chuẩn bị" : "Xem nhanh nguyên liệu của món " + cake.name}</span>
          </button>
          ${
            showIngredientsDrawer
              ? `
            <div class="mt-2 p-3 rounded-2xl bg-white border border-stone-200 grid grid-cols-1 sm:grid-cols-2 gap-1.5 max-h-40 overflow-y-auto text-xs">
              ${cake.ingredients
                .map(
                  (ing) => `
                <div class="flex items-center justify-between gap-2 p-1.5 rounded-lg bg-stone-50">
                  <span class="font-semibold text-stone-800">${ing.item}</span>
                  <strong class="text-rose-700">${ing.amount}</strong>
                </div>
              `
                )
                .join("")}
            </div>
          `
              : ""
          }
        </div>

        <div class="flex items-center justify-between gap-2 pt-3 border-t border-stone-200">
          <button
            type="button"
            id="wizard-prev-step-btn"
            class="pop-btn px-4 py-2.5 rounded-xl text-xs font-extrabold ${
              stepIdx === 0 ? "bg-stone-200 text-stone-500" : "bg-white hover:bg-amber-50 text-stone-900"
            }"
          >
            <i class="fa-solid fa-arrow-left mr-1"></i> Bước trước
          </button>

          <button
            type="button"
            id="wizard-open-full-detail-btn"
            class="text-xs font-extrabold text-stone-600 hover:text-[#0F4C3A] underline"
          >
            Mở trang công thức đầy đủ
          </button>

          <button
            type="button"
            id="wizard-next-step-btn"
            class="shimmer-btn pop-btn bg-[#0F4C3A] hover:bg-[#093528] text-amber-200 px-4 py-2.5 rounded-xl text-xs font-extrabold flex items-center gap-1.5"
          >
            <span>${stepIdx < steps.length - 1 ? "Bước tiếp theo" : "Hoàn thành mẻ bánh"}</span>
            <i class="fa-solid ${stepIdx < steps.length - 1 ? "fa-arrow-right" : "fa-circle-check text-amber-300"}"></i>
          </button>
        </div>
      `;

      document.getElementById("wizard-cake-select")?.addEventListener("change", (e) => {
        currentCakeId = parseInt(e.target.value, 10) || 1;
        stepIdx = 0;
        renderWizard();
      });

      cookingWizardBody.querySelectorAll(".wizard-step-pill").forEach((pill) => {
        pill.addEventListener("click", () => {
          stepIdx = parseInt(pill.getAttribute("data-wizard-step-pill"), 10) || 0;
          renderWizard();
        });
      });

      const timerDisplayEl = document.getElementById("wizard-timer-display");
      const timerStatusEl = document.getElementById("wizard-timer-status");
      const timerToggleLabel = document.getElementById("wizard-timer-toggle-label");

      document.getElementById("wizard-timer-minus-btn")?.addEventListener("click", () => {
        timerRemaining = Math.max(30, timerRemaining - 60);
        if (timerDisplayEl) timerDisplayEl.textContent = formatCountdownTime(timerRemaining);
      });

      document.getElementById("wizard-timer-plus-btn")?.addEventListener("click", () => {
        timerRemaining += 60;
        if (timerDisplayEl) timerDisplayEl.textContent = formatCountdownTime(timerRemaining);
      });

      document.getElementById("wizard-timer-toggle-btn")?.addEventListener("click", () => {
        if (timerRunning) {
          clearWizardTimer();
          timerRunning = false;
          if (timerToggleLabel) timerToggleLabel.textContent = "Tiếp tục";
          if (timerStatusEl) timerStatusEl.textContent = "ĐANG TẠM DỪNG";
        } else {
          timerRunning = true;
          if (timerToggleLabel) timerToggleLabel.textContent = "Tạm dừng";
          if (timerStatusEl) timerStatusEl.textContent = `ĐANG ĐẾM NGƯỢC BƯỚC ${curStep.stepNumber}`;
          wizardTimerInterval = setInterval(() => {
            timerRemaining = Math.max(0, timerRemaining - 1);
            if (timerDisplayEl) timerDisplayEl.textContent = formatCountdownTime(timerRemaining);
            if (timerRemaining <= 0) {
              clearWizardTimer();
              timerRunning = false;
              if (timerStatusEl) timerStatusEl.textContent = `ĐÃ HOÀN TẤT BƯỚC ${curStep.stepNumber}!`;
              if (timerToggleLabel) timerToggleLabel.textContent = "Đếm lại";
              playKitchenBellChime();
              showAppToast(`Hoàn tất thời gian Bước ${curStep.stepNumber}: ${curStep.title}!`);
            }
          }, 1000);
        }
      });

      const speakBtn = document.getElementById("wizard-speak-step-btn");
      speakBtn?.addEventListener("click", () => {
        const text = `${cake.name}, Bước ${curStep.stepNumber}: ${curStep.title}. Thời gian ${curStep.duration}. ${curStep.detail}`;
        toggleVietnameseSpeech(text, speakBtn);
      });

      document.getElementById("wizard-toggle-ing-btn")?.addEventListener("click", () => {
        showIngredientsDrawer = !showIngredientsDrawer;
        renderWizard();
      });

      document.getElementById("wizard-prev-step-btn")?.addEventListener("click", () => {
        if (stepIdx > 0) {
          stepIdx -= 1;
          renderWizard();
        }
      });

      document.getElementById("wizard-next-step-btn")?.addEventListener("click", () => {
        if (stepIdx < steps.length - 1) {
          stepIdx += 1;
          renderWizard();
        } else {
          playKitchenBellChime();
          triggerCelebrationConfetti();
          showAppToast(`Chúc mừng bạn đã hoàn thành món ${cake.name}!`);
          clearWizardTimer();
          cookingWizardModal.classList.add("hidden");
        }
      });

      document.getElementById("wizard-open-full-detail-btn")?.addEventListener("click", () => {
        clearWizardTimer();
        cookingWizardModal.classList.add("hidden");
        navigateToSpoke(cake.id);
      });
    };

    renderWizard();
  }
  window.openCookingWizardModal = openCookingWizardModal;

  function openCakeLightboxModal(cakeId) {
    if (!cakeLightboxModal || !cakeLightboxBody) return;
    const cake = data.find((d) => d.id === parseInt(cakeId, 10)) || data[0];
    cakeLightboxModal.classList.remove("hidden");

    cakeLightboxBody.innerHTML = `
      <div class="relative h-72 sm:h-80 bg-stone-950">
        <img src="${cake.image}" alt="${cake.name}" class="w-full h-full object-cover" />
        <div class="absolute inset-0 bg-gradient-to-t from-stone-950/90 via-stone-950/20 to-transparent"></div>
        <div class="absolute top-3.5 left-3.5 flex items-center gap-2">
          <img src="${getRegionIconById(cake.regionId)}" alt="" class="w-10 h-10 rounded-full object-cover region-medallion-img" />
          <span class="px-3 py-1 rounded-full bg-[#0F4C3A] text-amber-200 text-xs font-extrabold border border-amber-300">
            ${cake.categoryName}
          </span>
        </div>
        <div class="absolute bottom-3.5 left-4 right-4 text-white">
          <p class="text-xs font-bold text-amber-300">${cake.localSpot}</p>
          <h3 class="font-serif-heritage text-2xl font-bold mt-0.5">${cake.id}. ${cake.name}</h3>
        </div>
      </div>

      <div class="p-5 space-y-3 text-xs md:text-sm">
        <div class="p-3 rounded-2xl bg-[#FAF6EE] border border-[#C8922A]/50">
          <p class="font-extrabold text-rose-700 uppercase text-[11px] mb-0.5">Xuất xứ &amp; Văn hóa:</p>
          <p class="text-stone-800 font-medium leading-relaxed">${cake.originExact}</p>
        </div>
        <div class="p-3 rounded-2xl bg-white border border-stone-200">
          <p class="font-extrabold text-[#0F4C3A] uppercase text-[11px] mb-0.5">Thành phần &amp; Công thức cốt lõi:</p>
          <p class="text-stone-700 leading-relaxed">${cake.recipeExact}</p>
        </div>
        <div class="flex items-center justify-between gap-2 pt-2">
          <button
            type="button"
            id="lightbox-start-wizard-btn"
            class="pop-btn flex-1 bg-rose-700 hover:bg-rose-800 text-amber-100 font-extrabold text-xs py-2.5 px-3 rounded-xl flex items-center justify-center gap-1.5"
          >
            <i class="fa-solid fa-fire-burner text-amber-300"></i>
            <span>Hướng Dẫn Từng Bước</span>
          </button>
          <button
            type="button"
            id="lightbox-open-detail-btn"
            class="shimmer-btn pop-btn flex-1 bg-[#0F4C3A] hover:bg-[#093528] text-amber-200 font-extrabold text-xs py-2.5 px-3 rounded-xl flex items-center justify-center gap-1.5"
          >
            <span>Xem toàn bộ công thức</span>
            <i class="fa-solid fa-arrow-right"></i>
          </button>
        </div>
      </div>
    `;

    document.getElementById("lightbox-start-wizard-btn")?.addEventListener("click", () => {
      cakeLightboxModal.classList.add("hidden");
      openCookingWizardModal(cake.id, 0);
    });

    document.getElementById("lightbox-open-detail-btn")?.addEventListener("click", () => {
      cakeLightboxModal.classList.add("hidden");
      navigateToSpoke(cake.id);
    });
  }

  // Khởi tạo thanh tiến trình đọc, nút bật/tắt hiệu ứng lễ hội, điều hướng nhanh và đóng mở modal
  const scrollBarEl = document.getElementById("scroll-progress-bar");
  window.addEventListener("scroll", () => {
    if (!scrollBarEl) return;
    const docH = document.documentElement.scrollHeight - window.innerHeight;
    const pct = docH > 0 ? Math.min(100, Math.max(0, (window.scrollY / docH) * 100)) : 0;
    scrollBarEl.style.width = `${pct}%`;
  }, { passive: true });

  const STORAGE_MOTION_KEY = "khmer_cakes_motion_fx";
  const motionBtn = document.getElementById("toggle-motion-fx-btn");
  const motionLabel = document.getElementById("motion-fx-label");
  let motionState = "on";
  try {
    const savedMotion = localStorage.getItem(STORAGE_MOTION_KEY);
    if (savedMotion === "off") motionState = "off";
  } catch (e) {}
  const applyMotionState = (st) => {
    document.documentElement.setAttribute("data-motion", st);
    if (motionLabel) motionLabel.textContent = st === "off" ? "Hiệu ứng: Tắt" : "Hiệu ứng: Bật";
  };
  applyMotionState(motionState);
  motionBtn?.addEventListener("click", () => {
    motionState = motionState === "on" ? "off" : "on";
    try {
      localStorage.setItem(STORAGE_MOTION_KEY, motionState);
    } catch (e) {}
    applyMotionState(motionState);
    showAppToast(motionState === "on" ? "Đã bật hiệu ứng cánh sen & chuyển động lễ hội" : "Đã tạm tắt hiệu ứng chuyển động");
  });

  const heroSlides = [
    { src: BRAND_ICONS.artisanBanner, caption: "Bà con quây quần gói bánh truyền thống" },
    { src: BRAND_ICONS.heroOriginal, caption: "Mâm bánh dân gian Khmer truyền thống" },
    { src: BRAND_ICONS.ingredientsFlatlay, caption: "Nguyên liệu tự nhiên: lá bù ngót, lá dứa, lá mơ, đường thốt nốt" },
    { src: BRAND_ICONS.qrExhibit, caption: "Bánh truyền thống kèm mã QR tra cứu nhanh" }
  ];

  document.querySelectorAll(".hero-thumb-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = parseInt(btn.getAttribute("data-hero-slide"), 10) || 0;
      const slide = heroSlides[idx] || heroSlides[0];
      const mainImg = document.getElementById("hero-main-showcase-img");
      const capEl = document.getElementById("hero-img-caption");
      if (mainImg) mainImg.src = slide.src;
      if (capEl) capEl.textContent = slide.caption;
      document.querySelectorAll(".hero-thumb-btn").forEach((b) => b.classList.remove("active-thumb"));
      btn.classList.add("active-thumb");
    });
  });

  // === HỆ THỐNG HIỆU ỨNG THƠ MỘNG TÌNH YÊU QUÊ HƯƠNG SÔNG NƯỚC VĨNH LONG ===
  let currentHeroSlideIdx = 0;
  setInterval(() => {
    if (document.documentElement.getAttribute("data-motion") === "off") return;
    if (hubView.classList.contains("hidden")) return;
    currentHeroSlideIdx = (currentHeroSlideIdx + 1) % heroSlides.length;
    const slide = heroSlides[currentHeroSlideIdx];
    const mainImg = document.getElementById("hero-main-showcase-img");
    const capEl = document.getElementById("hero-img-caption");
    if (mainImg && slide) mainImg.src = slide.src;
    if (capEl && slide) capEl.textContent = slide.caption;
    document.querySelectorAll(".hero-thumb-btn").forEach((b, i) => {
      if (i === currentHeroSlideIdx) b.classList.add("active-thumb");
      else b.classList.remove("active-thumb");
    });
  }, 7500);

  const HOMELAND_POEMS = [
    {
      l1: '"Sông Cổ Chiên chở nặng phù sa, khói bếp Trà Cuôn ấm nghĩa nhà,',
      l2: 'Cốm dẹp trăng rằm thơm xứ sở, ngọt lành hồn bánh đất ông cha."'
    },
    {
      l1: '"Đọt dừa Bến Tre quấn nghĩa tình, lá mơ Vĩnh Long mát bóng đình,',
      l2: 'Mười bốn thức quà thơm thảo mộc, giữ trọn ngàn năm nếp quê mình."'
    },
    {
      l1: '"Trăng lên Ao Bà Om sáng tỏ, nhịp chày giã cốm vọng phum xưa,',
      l2: 'Thốt nốt vàng ươm màu nắng mới, ngọt ngào hương vị mấy mùa mưa."'
    },
    {
      l1: '"Ai về Vĩnh Long miền đất mới, ba vùng hội tụ một dòng sông,',
      l2: 'Bánh tét xanh ngọc màu lá biếc, nghĩa nặng tình sâu khắp tấm lòng."'
    }
  ];
  let poemIdx = 0;
  document.getElementById("hero-next-poem-btn")?.addEventListener("click", () => {
    poemIdx = (poemIdx + 1) % HOMELAND_POEMS.length;
    const p = HOMELAND_POEMS[poemIdx];
    const l1El = document.getElementById("poetic-verse-line-1");
    const l2El = document.getElementById("poetic-verse-line-2");
    if (l1El) l1El.textContent = p.l1;
    if (l2El) l2El.textContent = p.l2;
    showAppToast("Đã đổi khúc thơ tình yêu quê hương Vĩnh Long!");
  });

  // === HỆ THỐNG MÔ PHỎNG VẬT LÝ 3D CHÂN THẬT: LÁ RƠI, HOA DẦU XOAY, CÁNH SEN & ĐOM ĐÓM QUÊ HƯƠNG ===
  const POETIC_SCENES = [
    {
      id: "falling-leaves",
      label: "Cảnh quê: Lá Rơi & Hoa Dầu",
      toast: "Hiệu ứng chân thật: Lá cây quê hương chao nghiêng 3D, lá dứa & chong chóng hoa dầu xoay trong gió"
    },
    {
      id: "lotus-breeze",
      label: "Cảnh quê: Cánh Sen & Mùa Lúa",
      toast: "Hiệu ứng chân thật: Cánh hoa sen hồng 3D, lá non & hạt lúa vàng bay trong nắng sớm"
    },
    {
      id: "firefly-night",
      label: "Cảnh quê: Đom Đóm & Lá Đêm",
      toast: "Hiệu ứng chân thật: Đom đóm miền Tây phát sáng có đuôi sáng mờ & lá rơi dưới ánh trăng"
    },
    {
      id: "morning-rain",
      label: "Cảnh quê: Mưa Phùn & Lá Ướt",
      toast: "Hiệu ứng chân thật: Mưa bụi nắng mai xiên chéo, sương sớm & lá rơi ven sông"
    }
  ];
  let activePoeticSceneIdx = 0;
  const sceneBtn = document.getElementById("cycle-poetic-scene-btn");
  const sceneLabel = document.getElementById("poetic-scene-label");

  const atmoCanvas = document.getElementById("homeland-atmosphere-canvas");
  const atmoCtx = atmoCanvas ? atmoCanvas.getContext("2d") : null;
  let atmoParticles = [];
  let clickBurstParticles = [];

  // Luồng gió tự nhiên êm đềm thay đổi nhẹ nhàng theo thời gian (không đẩy/né trỏ chuột)
  let globalWindTime = 0;

  const resizeAtmoCanvas = () => {
    if (!atmoCanvas) return;
    atmoCanvas.width = window.innerWidth;
    atmoCanvas.height = window.innerHeight;
  };
  resizeAtmoCanvas();
  window.addEventListener("resize", resizeAtmoCanvas, { passive: true });

  // Bảng màu thực vật tự nhiên của các loại lá quê hương
  const LEAF_PALETTES = [
    // Lá xanh non miệt vườn
    { base: "#15803D", mid: "#22C55E", tip: "#86EFAC", back: "#4ADE80", vein: "#BBF7D0", stem: "#14532D" },
    // Lá bồ đề / lá cây cổ thụ xanh ngọc
    { base: "#0F4C3A", mid: "#0D9488", tip: "#5EEAD4", back: "#2DD4BF", vein: "#99F6E4", stem: "#064E3B" },
    // Lá thu vàng nắng sớm
    { base: "#B45309", mid: "#F59E0B", tip: "#FDE047", back: "#FBBF24", vein: "#FEF08A", stem: "#78350F" },
    // Lá vàng cam chiều quê
    { base: "#9A3412", mid: "#EA580C", tip: "#FDBA74", back: "#FB923C", vein: "#FFEDD5", stem: "#7C2D12" },
    // Lá xanh cốm lúa non
    { base: "#3F6212", mid: "#65A30D", tip: "#BEF264", back: "#84CC16", vein: "#ECFCCB", stem: "#365314" }
  ];

  // 1. Vẽ chiếc lá gân xương cá 3D chân thật (có cuống lá, đuôi lá uốn nhẹ, gân chính, gân phụ và độ bóng nắng)
  function drawRealisticBroadLeaf(ctx, size, pal, flipScaleY, tiltAngle, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.rotate(tiltAngle);
    // Bóng đổ mềm dưới chiếc lá tạo chiều sâu không gian
    ctx.shadowColor = "rgba(15, 35, 25, 0.18)";
    ctx.shadowBlur = 5;
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 3;

    // Phép chiếu lật mặt 3D (khi chiếc lá xoay lật trong không trung)
    const clampedFlip = Math.abs(flipScaleY) < 0.14 ? (flipScaleY >= 0 ? 0.14 : -0.14) : flipScaleY;
    ctx.scale(1, clampedFlip);

    // Cuống lá mảnh hơi cong ở gốc
    ctx.strokeStyle = pal.stem;
    ctx.lineWidth = Math.max(1, size * 0.09);
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-size * 1.18, size * 0.1);
    ctx.quadraticCurveTo(-size * 0.92, 0, -size * 0.72, 0);
    ctx.stroke();

    // Phiến lá tự nhiên có mũi nhọn hơi uốn lượn
    const grad = ctx.createLinearGradient(-size * 0.75, -size * 0.4, size * 1.05, size * 0.4);
    if (flipScaleY >= 0) {
      grad.addColorStop(0, pal.base);
      grad.addColorStop(0.55, pal.mid);
      grad.addColorStop(1, pal.tip);
    } else {
      // Mặt lưng của chiếc lá nhạt và mờ hơn mặt trên
      grad.addColorStop(0, pal.base);
      grad.addColorStop(0.6, pal.back);
      grad.addColorStop(1, pal.mid);
    }

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(-size * 0.74, 0);
    // Cạnh trên của phiến lá
    ctx.bezierCurveTo(-size * 0.48, -size * 0.68, size * 0.32, -size * 0.58, size * 1.08, -size * 0.06);
    // Đuôi lá nhọn uốn nhẹ
    ctx.quadraticCurveTo(size * 0.92, size * 0.04, size * 1.08, -size * 0.06);
    // Cạnh dưới của phiến lá
    ctx.bezierCurveTo(size * 0.35, size * 0.62, -size * 0.45, size * 0.68, -size * 0.74, 0);
    ctx.closePath();
    ctx.fill();

    // Tắt shadow khi vẽ gân lá để gân sắc nét
    ctx.shadowColor = "transparent";

    // Sống lá chính (Midrib)
    ctx.strokeStyle = pal.vein;
    ctx.globalAlpha = alpha * 0.72;
    ctx.lineWidth = Math.max(0.7, size * 0.055);
    ctx.beginPath();
    ctx.moveTo(-size * 0.72, 0);
    ctx.quadraticCurveTo(size * 0.1, -size * 0.03, size * 0.95, -size * 0.05);
    ctx.stroke();

    // Các cặp gân lá phụ (Lateral veins)
    ctx.lineWidth = Math.max(0.45, size * 0.032);
    ctx.globalAlpha = alpha * 0.48;
    const veinOffsets = [-0.42, -0.12, 0.18, 0.46];
    veinOffsets.forEach((vx, i) => {
      const span = (0.44 - i * 0.07) * size;
      ctx.beginPath();
      ctx.moveTo(vx * size, -size * 0.01);
      ctx.quadraticCurveTo((vx + 0.18) * size, -span * 0.65, (vx + 0.32) * size, -span);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(vx * size, 0);
      ctx.quadraticCurveTo((vx + 0.18) * size, span * 0.65, (vx + 0.32) * size, span);
      ctx.stroke();
    });

    ctx.restore();
  }

  // 2. Vẽ lá tre / lá dứa thon dài uốn cong mềm mại trong gió
  function drawRealisticSlenderLeaf(ctx, size, pal, flipScaleY, tiltAngle, bend, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.rotate(tiltAngle);
    const clampedFlip = Math.abs(flipScaleY) < 0.18 ? (flipScaleY >= 0 ? 0.18 : -0.18) : flipScaleY;
    ctx.scale(1, clampedFlip);

    const len = size * 1.45;
    const wid = size * 0.24;
    const grad = ctx.createLinearGradient(-len, 0, len, 0);
    grad.addColorStop(0, pal.base);
    grad.addColorStop(0.5, pal.mid);
    grad.addColorStop(1, pal.tip);

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(-len, 0);
    ctx.quadraticCurveTo(0, -wid + bend * size, len, bend * size * 0.6);
    ctx.quadraticCurveTo(0, wid + bend * size, -len, 0);
    ctx.closePath();
    ctx.fill();

    // Gân sáng dọc giữa lá dứa / lá tre
    ctx.strokeStyle = pal.vein;
    ctx.globalAlpha = alpha * 0.65;
    ctx.lineWidth = Math.max(0.6, size * 0.04);
    ctx.beginPath();
    ctx.moveTo(-len * 0.9, 0);
    ctx.quadraticCurveTo(0, bend * size, len * 0.88, bend * size * 0.55);
    ctx.stroke();

    ctx.restore();
  }

  // 3. Vẽ trái Hoa Dầu hai cánh xoay tít như chong chóng (đặc trưng hàng cây dầu quanh chùa Khmer)
  function drawRealisticDipterocarpSeed(ctx, size, spinPhase, tiltAngle, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.rotate(tiltAngle);

    const wingSpread = Math.cos(spinPhase);
    // Hai cánh hoa dầu vươn lên chữ V và xoay tròn 3D
    [-1, 1].forEach((dir) => {
      ctx.save();
      ctx.scale(dir * (0.35 + 0.65 * Math.abs(wingSpread)), 1);
      ctx.rotate(-0.38);
      const wGrad = ctx.createLinearGradient(0, 0, 0, -size * 1.65);
      wGrad.addColorStop(0, "#92400E");
      wGrad.addColorStop(0.45, "#D97706");
      wGrad.addColorStop(1, "#FDE047");
      ctx.fillStyle = wGrad;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(-size * 0.28, -size * 0.55, -size * 0.36, -size * 1.45, 0, -size * 1.68);
      ctx.bezierCurveTo(size * 0.32, -size * 1.45, size * 0.22, -size * 0.55, 0, 0);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });

    // Hạt tròn nhỏ ở tâm dưới
    const nutGrad = ctx.createRadialGradient(-size * 0.06, size * 0.06, 0.5, 0, size * 0.1, size * 0.26);
    nutGrad.addColorStop(0, "#B45309");
    nutGrad.addColorStop(1, "#451A03");
    ctx.fillStyle = nutGrad;
    ctx.beginPath();
    ctx.arc(0, size * 0.1, size * 0.22, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  // 4. Vẽ cánh Hoa Sen Hồng 3D mềm mại (gốc trắng ngà chuyển sắc hồng sen ở đầu cánh)
  function drawRealisticLotusPetal(ctx, size, flipScaleY, tiltAngle, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.rotate(tiltAngle);
    const clampedFlip = Math.abs(flipScaleY) < 0.2 ? (flipScaleY >= 0 ? 0.2 : -0.2) : flipScaleY;
    ctx.scale(1, clampedFlip);

    const pGrad = ctx.createLinearGradient(-size * 0.85, 0, size * 0.95, 0);
    pGrad.addColorStop(0, "#FEF9C3");
    pGrad.addColorStop(0.32, "#FBCFE8");
    pGrad.addColorStop(0.75, "#FB7185");
    pGrad.addColorStop(1, "#BE123C");

    ctx.fillStyle = pGrad;
    ctx.beginPath();
    ctx.moveTo(-size * 0.82, 0);
    ctx.bezierCurveTo(-size * 0.35, -size * 0.65, size * 0.45, -size * 0.58, size * 0.94, 0);
    ctx.bezierCurveTo(size * 0.45, size * 0.58, -size * 0.35, size * 0.65, -size * 0.82, 0);
    ctx.closePath();
    ctx.fill();

    // Đường vân mịn dọc cánh sen
    ctx.strokeStyle = "rgba(255, 255, 255, 0.45)";
    ctx.lineWidth = Math.max(0.5, size * 0.035);
    ctx.beginPath();
    ctx.moveTo(-size * 0.72, 0);
    ctx.quadraticCurveTo(0, -size * 0.05, size * 0.82, 0);
    ctx.stroke();

    ctx.restore();
  }

  const createSceneParticle = (sceneId, randomY = false) => {
    const w = window.innerWidth || 1280;
    const h = window.innerHeight || 800;
    // Lớp chiều sâu (depth: 0.65 = xa, 1.0 = trung bình, 1.35 = gần)
    const depth = 0.65 + Math.random() * 0.7;
    const pal = LEAF_PALETTES[Math.floor(Math.random() * LEAF_PALETTES.length)];

    if (sceneId === "firefly-night") {
      const isLeaf = Math.random() < 0.38;
      if (!isLeaf) {
        const startX = Math.random() * w;
        const startY = randomY ? Math.random() * h : h + 20;
        return {
          kind: "firefly",
          x: startX,
          y: startY,
          vx: (Math.random() - 0.5) * 0.8,
          vy: -(0.25 + Math.random() * 0.55),
          size: (2.2 + Math.random() * 2.4) * depth,
          phase: Math.random() * Math.PI * 2,
          trail: [{ x: startX, y: startY }],
          alpha: 0.75 * Math.min(1, depth)
        };
      }
    }

    if (sceneId === "morning-rain") {
      const isRain = Math.random() < 0.58;
      if (isRain) {
        return {
          kind: "raindrop",
          x: Math.random() * (w + 200) - 100,
          y: randomY ? Math.random() * h : -30,
          vx: 1.4 + Math.random() * 0.8,
          vy: 6.5 + Math.random() * 4.5,
          len: (14 + Math.random() * 14) * depth,
          alpha: 0.22 + Math.random() * 0.22
        };
      }
    }

    const r = Math.random();
    let kind = "broad-leaf";
    if (sceneId === "falling-leaves") {
      kind = r < 0.52 ? "broad-leaf" : r < 0.80 ? "slender-leaf" : "dipterocarp-seed";
    } else if (sceneId === "lotus-breeze") {
      kind = r < 0.55 ? "lotus-petal" : r < 0.82 ? "broad-leaf" : "slender-leaf";
    } else {
      kind = r < 0.65 ? "broad-leaf" : "slender-leaf";
    }

    return {
      kind,
      depth,
      pal,
      x: Math.random() * (w + 120) - 60,
      y: randomY ? Math.random() * h : -35 - Math.random() * 60,
      vx: (Math.random() - 0.35) * 0.6 * depth,
      vy: (0.65 + Math.random() * 0.75) * depth,
      size: (8.5 + Math.random() * 5.5) * depth,
      swayPhase: Math.random() * Math.PI * 2,
      swaySpeed: 0.016 + Math.random() * 0.018,
      swayAmp: (0.75 + Math.random() * 0.95) * depth,
      flipPhase: Math.random() * Math.PI * 2,
      flipSpeed: kind === "dipterocarp-seed" ? 0.14 + Math.random() * 0.08 : 0.024 + Math.random() * 0.025,
      baseRot: (Math.random() - 0.5) * 0.5,
      bend: (Math.random() - 0.5) * 0.35,
      alpha: Math.min(0.88, (0.52 + Math.random() * 0.32) * depth)
    };
  };

  const initAtmoParticles = () => {
    const sceneId = POETIC_SCENES[activePoeticSceneIdx].id;
    const count = sceneId === "morning-rain" ? 42 : 30;
    atmoParticles = Array.from({ length: count }, () => createSceneParticle(sceneId, true));
  };
  initAtmoParticles();

  sceneBtn?.addEventListener("click", () => {
    activePoeticSceneIdx = (activePoeticSceneIdx + 1) % POETIC_SCENES.length;
    const sc = POETIC_SCENES[activePoeticSceneIdx];
    if (sceneLabel) sceneLabel.textContent = sc.label;
    if (motionState === "off") {
      motionState = "on";
      applyMotionState("on");
    }
    initAtmoParticles();
    showAppToast(sc.toast);
  });

  // Khi bấm hoặc chạm màn hình: tạo gợn sóng nước và tung những chiếc lá non + cánh sen 3D bay theo gió
  document.addEventListener("pointerdown", (e) => {
    if (document.documentElement.getAttribute("data-motion") === "off") return;
    if (e.target && (e.target.closest("input") || e.target.closest("select") || e.target.closest("textarea"))) return;

    const ripple = document.createElement("div");
    ripple.className = "homeland-click-ripple";
    ripple.style.left = `${e.clientX}px`;
    ripple.style.top = `${e.clientY}px`;
    document.body.appendChild(ripple);
    setTimeout(() => ripple.remove(), 860);

    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI * 2 * i) / 6 + (Math.random() - 0.5) * 0.35;
      const speed = 1.2 + Math.random() * 1.8;
      const pal = LEAF_PALETTES[i % LEAF_PALETTES.length];
      clickBurstParticles.push({
        kind: i % 2 === 0 ? "broad-leaf" : "lotus-petal",
        pal,
        x: e.clientX,
        y: e.clientY,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 0.5,
        size: 8 + Math.random() * 4,
        flipPhase: Math.random() * Math.PI * 2,
        flipSpeed: 0.06 + Math.random() * 0.04,
        tiltAngle: angle,
        vRot: (Math.random() - 0.5) * 0.05,
        alpha: 0.92
      });
    }
  }, { passive: true });

  const renderAtmoLoop = () => {
    if (atmoCtx && atmoCanvas && document.documentElement.getAttribute("data-motion") !== "off") {
      const w = atmoCanvas.width;
      const h = atmoCanvas.height;
      atmoCtx.clearRect(0, 0, w, h);
      const sceneId = POETIC_SCENES[activePoeticSceneIdx].id;

      globalWindTime += 0.012;
      // Gió tự nhiên thổi từng đợt nhẹ nhàng qua cánh đồng và rặng dừa
      const naturalBreezeX = Math.sin(globalWindTime) * 0.38 + Math.sin(globalWindTime * 0.37) * 0.25;

      atmoParticles.forEach((p, idx) => {
        if (p.kind === "raindrop") {
          p.x += p.vx + naturalBreezeX * 0.5;
          p.y += p.vy;
          atmoCtx.save();
          atmoCtx.strokeStyle = "rgba(186, 230, 253, 0.45)";
          atmoCtx.globalAlpha = p.alpha;
          atmoCtx.lineWidth = 1.15;
          atmoCtx.lineCap = "round";
          atmoCtx.beginPath();
          atmoCtx.moveTo(p.x, p.y);
          atmoCtx.lineTo(p.x - p.vx * 1.8, p.y - p.len);
          atmoCtx.stroke();
          atmoCtx.restore();

          if (p.y > h + 30 || p.x > w + 60) {
            atmoParticles[idx] = createSceneParticle(sceneId, false);
          }
          return;
        }

        if (p.kind === "firefly") {
          p.phase += 0.04;
          p.x += p.vx + Math.sin(p.phase) * 0.45 + naturalBreezeX * 0.25;
          p.y += p.vy + Math.cos(p.phase * 0.8) * 0.25;
          p.trail.push({ x: p.x, y: p.y });
          if (p.trail.length > 6) p.trail.shift();

          atmoCtx.save();
          // Vẽ vệt đuôi sáng mờ của đom đóm đêm quê
          if (p.trail.length > 1) {
            atmoCtx.beginPath();
            atmoCtx.moveTo(p.trail[0].x, p.trail[0].y);
            for (let t = 1; t < p.trail.length; t++) {
              atmoCtx.lineTo(p.trail[t].x, p.trail[t].y);
            }
            atmoCtx.strokeStyle = "rgba(250, 204, 21, 0.22)";
            atmoCtx.lineWidth = p.size * 0.7;
            atmoCtx.lineCap = "round";
            atmoCtx.stroke();
          }

          const pulse = 0.35 + 0.65 * Math.abs(Math.sin(p.phase * 1.3));
          atmoCtx.globalAlpha = p.alpha * pulse;
          const grad = atmoCtx.createRadialGradient(p.x, p.y, 0.4, p.x, p.y, p.size * 3.2);
          grad.addColorStop(0, "#FEF9C3");
          grad.addColorStop(0.35, "#D9F99D");
          grad.addColorStop(0.7, "#FACC15");
          grad.addColorStop(1, "transparent");
          atmoCtx.fillStyle = grad;
          atmoCtx.beginPath();
          atmoCtx.arc(p.x, p.y, p.size * 3.2, 0, Math.PI * 2);
          atmoCtx.fill();
          atmoCtx.restore();

          if (p.y < -30 || p.y > h + 30 || p.x < -30 || p.x > w + 30) {
            atmoParticles[idx] = createSceneParticle(sceneId, false);
          }
          return;
        }

        // Chuyển động khí động học chân thật của chiếc lá rơi tự nhiên (chao nghiêng con lắc + lật mặt 3D êm dịu)
        p.swayPhase += p.swaySpeed;
        p.flipPhase += p.flipSpeed;

        const glideX = Math.sin(p.swayPhase) * p.swayAmp;
        // Khi chiếc lá chao ngang mạnh ở hai biên thì rơi chậm lại, khi chúc xuống giữa thì nhanh hơn
        const verticalFlutter = 1 - 0.28 * Math.abs(Math.cos(p.swayPhase));
        p.x += p.vx + glideX + naturalBreezeX * p.depth;
        p.y += p.vy * verticalFlutter;

        const flipScaleY = Math.cos(p.flipPhase);
        // Góc nghiêng của chiếc lá tự động chúc theo hướng chao lượn
        const tiltAngle = p.baseRot + Math.cos(p.swayPhase) * 0.42;

        atmoCtx.save();
        atmoCtx.translate(p.x, p.y);

        if (p.kind === "broad-leaf") {
          drawRealisticBroadLeaf(atmoCtx, p.size, p.pal, flipScaleY, tiltAngle, p.alpha);
        } else if (p.kind === "slender-leaf") {
          drawRealisticSlenderLeaf(atmoCtx, p.size, p.pal, flipScaleY, tiltAngle, p.bend, p.alpha);
        } else if (p.kind === "dipterocarp-seed") {
          drawRealisticDipterocarpSeed(atmoCtx, p.size * 0.82, p.flipPhase, tiltAngle * 0.35, p.alpha);
        } else if (p.kind === "lotus-petal") {
          drawRealisticLotusPetal(atmoCtx, p.size * 0.95, flipScaleY, tiltAngle, p.alpha);
        }

        atmoCtx.restore();

        if (p.y > h + 45 || p.x < -80 || p.x > w + 80) {
          atmoParticles[idx] = createSceneParticle(sceneId, false);
        }
      });


      // Vẽ các chiếc lá & cánh hoa sen 3D tung ra khi người dùng chạm màn hình
      for (let i = clickBurstParticles.length - 1; i >= 0; i--) {
        const bp = clickBurstParticles[i];
        bp.x += bp.vx + naturalBreezeX * 0.5;
        bp.y += bp.vy;
        bp.vy += 0.022; // trọng lực nhẹ
        bp.vx *= 0.985;
        bp.flipPhase += bp.flipSpeed;
        bp.tiltAngle += bp.vRot;
        bp.alpha -= 0.015;
        if (bp.alpha <= 0) {
          clickBurstParticles.splice(i, 1);
          continue;
        }
        atmoCtx.save();
        atmoCtx.translate(bp.x, bp.y);
        const flipY = Math.cos(bp.flipPhase);
        if (bp.kind === "broad-leaf") {
          drawRealisticBroadLeaf(atmoCtx, bp.size, bp.pal, flipY, bp.tiltAngle, Math.max(0, bp.alpha));
        } else {
          drawRealisticLotusPetal(atmoCtx, bp.size, flipY, bp.tiltAngle, Math.max(0, bp.alpha));
        }
        atmoCtx.restore();
      }
    }
    requestAnimationFrame(renderAtmoLoop);
  };
  requestAnimationFrame(renderAtmoLoop);

  // ============================================================================
  // [BỘ PHÁT FILE NHẠC NỀN TÙY CHỈNH CỦA BẠN]
  // Ghi chú:
  // - Hệ thống sẽ tự động lấy đường dẫn từ biến CUSTOM_MUSIC_FILE_PATH ở đầu <script>
  //   (hoặc thuộc tính src="..." của thẻ <audio id="custom-user-music-player"> ở đầu <body>).
  // - Ngoài ra bạn có thể bấm nút biểu tượng Thư mục kế bên nút "Bật Nhạc" để chọn trực tiếp
  //   file nhạc (.mp3, .wav, .ogg) từ máy tính / điện thoại của bạn!
  // ============================================================================
  const userAudioEl = document.getElementById("custom-user-music-player");
  const musicFileInput = document.getElementById("custom-music-file-input");
  const melodyBtn = document.getElementById("play-homeland-melody-btn");
  const pickMusicBtn = document.getElementById("pick-custom-music-btn");
  const melodyLabel = document.getElementById("homeland-melody-label");

  if (userAudioEl && typeof CUSTOM_MUSIC_FILE_PATH === "string" && CUSTOM_MUSIC_FILE_PATH.trim()) {
    userAudioEl.src = CUSTOM_MUSIC_FILE_PATH.trim();
  }

  const updateMusicButtonState = (playing) => {
    if (!melodyLabel || !melodyBtn) return;
    if (playing) {
      melodyLabel.innerHTML = '<span>Đang phát nhạc</span> <span class="melody-eq-bar"></span><span class="melody-eq-bar" style="animation-delay:0.2s"></span>';
      melodyBtn.classList.add("bg-amber-300", "text-stone-900");
    } else {
      melodyLabel.textContent = "Bật Nhạc";
      melodyBtn.classList.remove("bg-amber-300", "text-stone-900");
    }
  };

  melodyBtn?.addEventListener("click", async () => {
    if (!userAudioEl) return;
    if (!userAudioEl.paused) {
      userAudioEl.pause();
      updateMusicButtonState(false);
      showAppToast("Đã tạm dừng phát nhạc.");
      return;
    }
    try {
      await userAudioEl.play();
      updateMusicButtonState(true);
      showAppToast("Đang phát file nhạc nền của bạn!");
    } catch (err) {
      updateMusicButtonState(false);
      showAppToast("Hãy đặt file nhạc theo đường dẫn trong code hoặc chọn file nhạc (.mp3) từ máy của bạn!");
      musicFileInput?.click();
    }
  });

  pickMusicBtn?.addEventListener("click", () => {
    musicFileInput?.click();
  });

  musicFileInput?.addEventListener("change", async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file || !userAudioEl) return;
    const fileUrl = URL.createObjectURL(file);
    userAudioEl.src = fileUrl;
    try {
      await userAudioEl.play();
      updateMusicButtonState(true);
      showAppToast(`Đang phát file nhạc: ${file.name}`);
    } catch (err) {
      showAppToast(`Đã nạp file nhạc: ${file.name}. Bấm 'Bật Nhạc' để phát!`);
    }
  });

  // ============================================================================
  // [KHUNG TRỢ LÝ AI TRƯỜNG KHÁNH LUÔN HIỂN THỊ TRÊN MÀN HÌNH]
  // Luôn cố định ở góc màn hình khi cuộn trang, không cần lướt xuống cuối!
