  const tkLiveDock = document.getElementById("floating-tk-live-dock");
  const tkDockCollapseBtn = document.getElementById("toggle-tk-dock-collapse-btn");
  const tkDockHeaderToggle = document.getElementById("tk-dock-header-toggle");
  const tkDockCollapseIcon = document.getElementById("tk-dock-collapse-icon");
  const tkDockMessages = document.getElementById("tk-dock-messages");
  const tkDockInput = document.getElementById("tk-dock-input");
  const tkDockSendBtn = document.getElementById("tk-dock-send-btn");
  const tkDockVoiceBtn = document.getElementById("tk-dock-voice-btn");

  let isTkDockMinimized = true;
  const tkDockSubstatus = document.getElementById("tk-dock-substatus");

  const setTkDockMinimized = (minimized) => {
    isTkDockMinimized = minimized;
    if (!tkLiveDock) return;
    if (minimized) {
      tkLiveDock.classList.add("is-minimized");
      if (tkDockCollapseIcon) tkDockCollapseIcon.className = "fa-solid fa-comment-dots";
      if (tkDockSubstatus) tkDockSubstatus.textContent = "Bấm để mở khung hỏi đáp";
    } else {
      tkLiveDock.classList.remove("is-minimized");
      if (tkDockCollapseIcon) tkDockCollapseIcon.className = "fa-solid fa-minus";
      if (tkDockSubstatus) tkDockSubstatus.textContent = "Hiểu cả từ viết tắt • Bấm (-) để thu nhỏ";
      renderFloatingTkDockMessages();
      setTimeout(() => tkDockInput?.focus(), 80);
    }
  };

  tkDockCollapseBtn?.addEventListener("click", (e) => {
    e.stopPropagation();
    setTkDockMinimized(!isTkDockMinimized);
  });

  tkDockHeaderToggle?.addEventListener("click", () => {
    setTkDockMinimized(!isTkDockMinimized);
  });

  function renderFloatingTkDockMessages() {
    if (!tkDockMessages) return;
    const recentMsgs = aiChatHistory.slice(-6);
    tkDockMessages.innerHTML = recentMsgs
      .map((msg) => {
        if (msg.role === "user") {
          return `
            <div class="flex justify-end">
              <div class="bg-[#0F4C3A] text-amber-100 px-2.5 py-1.5 rounded-xl rounded-br-none max-w-[85%] text-[11px] font-semibold">
                ${msg.text}
              </div>
            </div>
          `;
        }
        const matchedCakes = (msg.matchedIds || [])
          .slice(0, 2)
          .map((id) => data.find((d) => d.id === id))
          .filter(Boolean);
        return `
          <div class="flex justify-start">
            <div class="bg-white p-2.5 rounded-xl rounded-bl-none border border-[#C8922A]/50 max-w-[96%] space-y-1.5 shadow-sm">
              <div class="flex items-center justify-between gap-1">
                <span class="text-[10px] font-extrabold text-[#0F4C3A] flex items-center gap-1">
                  <i class="fa-solid fa-comments text-rose-700"></i>
                  <span>Trường Khánh</span>
                </span>
              </div>
              <div class="text-[11px] text-stone-800 leading-relaxed">${formatAiReplyHtml(msg.text)}</div>
              ${
                matchedCakes.length > 0
                  ? `
                <div class="flex flex-wrap gap-1 pt-1 border-t border-dashed border-stone-200">
                  ${matchedCakes
                    .map(
                      (c) => `
                    <button
                      type="button"
                      data-dock-open-cake="${c.id}"
                      class="dock-open-cake-btn px-2 py-0.5 rounded-lg bg-[#0F4C3A] text-amber-200 text-[10px] font-extrabold flex items-center gap-1"
                    >
                      <span>${c.qrCodeId}: ${c.badgeText}</span>
                      <i class="fa-solid fa-arrow-right text-[9px]"></i>
                    </button>
                  `
                    )
                    .join("")}
                </div>
              `
                  : ""
              }
            </div>
          </div>
        `;
      })
      .join("");

    tkDockMessages.scrollTop = tkDockMessages.scrollHeight;

    tkDockMessages.querySelectorAll(".dock-open-cake-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const cid = parseInt(btn.getAttribute("data-dock-open-cake"), 10);
        if (cid) navigateToSpoke(cid);
      });
    });
  }

  const submitDockQuestion = async (rawQ) => {
    const cleanQ = String(rawQ || "").trim();
    if (!cleanQ) return;
    if (tkDockInput) tkDockInput.value = "";
    const snapshot = [...aiChatHistory];
    aiChatHistory.push({ role: "user", text: cleanQ });
    renderFloatingTkDockMessages();

    const ans = await fetchLiveFreeAiResponse(cleanQ, data, snapshot);
    aiChatHistory.push({
      role: "ai",
      text: ans.replyText,
      matchedIds: ans.matchedIds,
      sourceBadge: "Trường Khánh"
    });
    renderFloatingTkDockMessages();
    if (aiSmartKitchenContainer) renderAiSmartKitchenSection();
  };

  tkDockSendBtn?.addEventListener("click", () => {
    submitDockQuestion(tkDockInput?.value || "");
  });

  tkDockInput?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      submitDockQuestion(tkDockInput.value);
    }
  });

  tkDockVoiceBtn?.addEventListener("click", () => {
    startVoiceInputInto(tkDockInput, tkDockVoiceBtn, (spoken) => {
      submitDockQuestion(spoken);
    });
  });

  tkLiveDock?.querySelectorAll(".dock-quick-chip").forEach((chip) => {
    chip.addEventListener("click", () => {
      submitDockQuestion(chip.getAttribute("data-dock-prompt") || "");
    });
  });

  renderFloatingTkDockMessages();

