      const reg = btn.getAttribute("data-hero-region") || "tra-vinh";
      activeRegionId = reg;
      if (reg === "tra-vinh") activeFilter = "1. Khu vực Trà Vinh";
      else if (reg === "vinh-long") activeFilter = "2. Khu vực Vĩnh Long";
